+*{margin:0;padding:0;box-sizing:border-box}
+html,body{width:100%;height:100%;overflow:hidden;background:#0a0d12;font-family:"Segoe UI",system-ui,-apple-system,Roboto,Arial,sans-serif;color:#e8ecf1;user-select:none}
