#interact-tip{position:absolute;left:50%;bottom:30%;transform:translateX(-50%);background:rgba(0,0,0,.65);padding:8px 18px;border-radius:8px;border:1px solid #ffd27a;font-size:14px}
/* overlays */
.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 30%,rgba(30,45,70,.88),rgba(4,6,10,.94));z-index:10;backdrop-filter:blur(3px)}
.menu-card{text-align:center;max-width:620px;padding:34px 44px;background:rgba(10,14,20,.75);border:1px solid rgba(255,255,255,.12);border-radius:16px;box-shadow:0 20px 80px rgba(0,0,0,.6)}
.kicker{font-size:12px;letter-spacing:4px;color:#ffd27a;margin-bottom:6px}
.kicker.red{color:#ff5b5b}
h1{font-size:64px;letter-spacing:6px;font-weight:900;background:linear-gradient(180deg,#fff,#9fb2c8);-webkit-background-clip:text;background-clip:text;color:transparent}
h2{font-size:40px;letter-spacing:4px}
.sub{color:#9fb2c8;margin:10px 0 18px;font-size:14px}
.controls-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}
