import * as THREE from 'three';

/* ============================================================
   STRIKEPOINT — procedural wave-defense FPS (Three.js, no assets)
   ============================================================ */
const canvas = document.getElementById('game-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87b5e0);
scene.fog = new THREE.Fog(0xa8c0d8, 40, 130);

const camera = new THREE.PerspectiveCamera(75, innerWidth / innerHeight, 0.05, 400);
camera.rotation.order = 'YXZ';

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
renderer.setSize(innerWidth, innerHeight);

// ---------- lights ----------
scene.add(new THREE.HemisphereLight(0xbcd8ff, 0x6b6a5a, 0.75));
const sun = new THREE.DirectionalLight(0xfff1d6, 2.2);
sun.position.set(30, 46, 15);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -40; sun.shadow.camera.right = 40;
sun.shadow.camera.top = 40; sun.shadow.camera.bottom = -40;
sun.shadow.camera.far = 140; sun.shadow.bias = -0.0004;
scene.add(sun);
const fill = new THREE.DirectionalLight(0x9db8dd, 0.35);
fill.position.set(-25, 20, -30);
scene.add(fill);

// ---------- procedural canvas textures ----------
function canvasTex(size, fn, repeat = 1) {
  const c = document.createElement('canvas'); c.width = c.height = size;
  fn(c.getContext('2d'), size);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(repeat, repeat);
  t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
  return t;
}
const rnd = (a, b) => a + Math.random() * (b - a);
const groundTex = canvasTex(512, (g, s) => {
  g.fillStyle = '#5c5a52'; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 9000; i++) {
    const v = 70 + Math.random() * 50;
    g.fillStyle = `rgb(${v},${v - 4},${v - 12})`;
    g.fillRect(Math.random() * s, Math.random() * s, rnd(1, 3), rnd(1, 3));
  }
  g.strokeStyle = 'rgba(30,30,30,.55)'; g.lineWidth = 3;
  for (let i = 0; i <= 4; i++) {
    g.beginPath(); g.moveTo(i * s / 4, 0); g.lineTo(i * s / 4, s); g.stroke();
    g.beginPath(); g.moveTo(0, i * s / 4); g.lineTo(s, i * s / 4); g.stroke();
  }
  for (let i = 0; i < 26; i++) { // cracks / stains
    g.fillStyle = `rgba(20,18,14,${rnd(0.05, 0.22)})`;
    g.beginPath(); g.ellipse(Math.random() * s, Math.random() * s, rnd(6, 42), rnd(4, 20), rnd(0, 3), 0, 7); g.fill();
  }
}, 10);
const facadeTex = canvasTex(512, (g, s) => {
  g.fillStyle = '#8d8a82'; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 5000; i++) {
    const v = 120 + Math.random() * 40;
    g.fillStyle = `rgba(${v},${v - 3},${v - 10},.5)`;
    g.fillRect(Math.random() * s, Math.random() * s, 2, 2);
  }
  for (let r = 0; r < 3; r++) for (let c = 0; c < 6; c++) {
    const x = 20 + c * 80, y = 30 + r * 160;
    const lit = Math.random() < 0.3;
    g.fillStyle = lit ? '#ffd27a' : '#20262e';
    g.fillRect(x, y, 52, 90);
    g.fillStyle = 'rgba(255,255,255,.25)'; g.fillRect(x, y, 52, 8);
    g.strokeStyle = '#3a3a3a'; g.lineWidth = 4; g.strokeRect(x, y, 52, 90);
  }
});
const woodTex = canvasTex(256, (g, s) => {
  g.fillStyle = '#8a6a3f'; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 40; i++) {
    g.strokeStyle = `rgba(60,40,20,${rnd(0.2, 0.5)})`; g.lineWidth = rnd(1, 3);
    g.beginPath(); const y = Math.random() * s;
    g.moveTo(0, y); g.bezierCurveTo(s * .3, y + rnd(-6, 6), s * .7, y + rnd(-6, 6), s, y); g.stroke();
  }
  g.strokeStyle = '#4a3category'; g.strokeStyle = '#4a351d'; g.lineWidth = 10; g.strokeRect(0, 0, s, s);
});
const concreteTex = canvasTex(256, (g, s) => {
  g.fillStyle = '#9a978e'; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 3000; i++) {
    const v = 130 + Math.random() * 40;
    g.fillStyle = `rgba(${v},${v},${v - 5},.6)`;
    g.fillRect(Math.random() * s, Math.random() * s, 2, 2);
  }
});

// ---------- map ----------
const colliders = [];   // Box3 obstacles
const obstacles = [];   // meshes blocking LOS / bullets
function addCollider(mesh, pad = 0) {
  mesh.updateMatrixWorld(true);
  const b = new THREE.Box3().setFromObject(mesh);
  if (pad) b.expandByScalar(pad);
  colliders.push(b); obstacles.push(mesh);
  return b;
}
const ARENA = 31;

{
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(140, 140),
    new THREE.MeshStandardMaterial({ map: groundTex, roughness: 0.96, metalness: 0.02 })
  );
  ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true;
  scene.add(ground);
  // center plaza paint
  const plaza = new THREE.Mesh(
    new THREE.CircleGeometry(9, 40),
    new THREE.MeshStandardMaterial({ map: concreteTex, roughness: 0.9 })
  );
  plaza.rotation.x = -Math.PI / 2; plaza.position.y = 0.02; plaza.receiveShadow = true;
  scene.add(plaza);
}
// perimeter buildings
{
  const mat = new THREE.MeshStandardMaterial({ map: facadeTex, roughness: 0.85 });
  const mk = (x, z, w, d, ry) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, 13, d), mat);
    m.position.set(x, 6.5, z); m.rotation.y = ry;
    m.castShadow = m.receiveShadow = true; scene.add(m); addCollider(m);
  };
  mk(0, -42, 90, 10, 0); mk(0, 42, 90, 10, 0); mk(-42, 0, 10, 90, 0); mk(42, 0, 10, 90, 0);
  // corner towers
  const tmat = new THREE.MeshStandardMaterial({ color: 0x6e6a60, roughness: 0.9 });
  [[-42, -42], [42, -42], [-42, 42], [42, 42]].forEach(([x, z]) => {
    const t = new THREE.Mesh(new THREE.BoxGeometry(12, 20, 12), tmat);
    t.position.set(x, 10, z); t.castShadow = t.receiveShadow = true;
    scene.add(t); addCollider(t);
  });
}
// cover: crates, barriers, sandbags, barrels, tires, lamps
const crateMat = new THREE.MeshStandardMaterial({ map: woodTex, roughness: 0.8 });
const concMat = new THREE.MeshStandardMaterial({ map: concreteTex, roughness: 0.9 });
{
  const crateGeo = new THREE.BoxGeometry(1.2, 1.2, 1.2);
  const spots = [[-8, -6], [-6.4, -6], [-7.2, -4.6], [8, 5], [9.4, 5], [6, -9], [-5, 9], [12, -4], [-12, 4], [0, -13], [4, 12], [-14, -12], [14, 12], [16, 2], [-16, -2], [2, 16]];
  const inst = new THREE.InstancedMesh(crateGeo, crateMat, spots.length);
  const d = new THREE.Object3D();
  spots.forEach(([x, z], i) => {
    const h = i % 3 === 0 ? 2.4 : 1.2;
    d.position.set(x, h / 2 - 0.6 + 0.6, z); d.position.y = h / 2;
    d.rotation.y = rnd(0, Math.PI); d.updateMatrix();
    inst.setMatrixAt(i, d.matrix);
    const ghost = new THREE.Mesh(new THREE.BoxGeometry(1.2, h, 1.2));
    ghost.position.set(x, h / 2, z); ghost.updateMatrixWorld();
    colliders.push(new THREE.Box3().setFromObject(ghost));
  });
  inst.castShadow = inst.receiveShadow = true; scene.add(inst);
  obstacles.push(inst);
  // concrete barriers
  const bGeo = new THREE.BoxGeometry(2.4, 1.1, 0.6);
  [[-4, -2, 0.4], [4, 2, -0.4], [0, -7, 0], [0, 7, 0], [-11, 0, 1.2], [11, 0, 1.2]].forEach(([x, z, ry]) => {
    const b = new THREE.Mesh(bGeo, concMat);
    b.position.set(x, 0.55, z); b.rotation.y = ry;
    b.castShadow = b.receiveShadow = true; scene.add(b); addCollider(b);
  });
  // sandbag rings (low walls)
  const sandMat = new THREE.MeshStandardMaterial({ color: 0x9c8a62, roughness: 1 });
  [[-3, -11], [3, -11], [-3, 11], [3, 11]].forEach(([x, z]) => {
    const w = new THREE.Mesh(new THREE.BoxGeometry(3.2, 1.0, 0.8), sandMat);
    w.position.set(x, 0.5, z); w.castShadow = w.receiveShadow = true;
    scene.add(w); addCollider(w);
  });
  // barrels
  const barrelGeo = new THREE.CylinderGeometry(0.42, 0.42, 0.95, 14);
  const red = new THREE.MeshStandardMaterial({ color: 0x8c2f22, roughness: 0.6, metalness: 0.4 });
  const blue = new THREE.MeshStandardMaterial({ color: 0x2b4d6e, roughness: 0.6, metalness: 0.4 });
  [[-9, 8, red], [-8.2, 8.6, blue], [9, -8, blue], [9.8, -7.4, red], [-18, 6, red], [18, -6, blue]].forEach(([x, z, m]) => {
    const b = new THREE.Mesh(barrelGeo, m);
    b.position.set(x, 0.48, z); b.castShadow = b.receiveShadow = true;
    scene.add(b); addCollider(b);
  });
  // lamps (2 real lights)
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x22262b, roughness: 0.5, metalness: 0.8 });
  const lampMat = new THREE.MeshStandardMaterial({ color: 0xfff2cc, emissive: 0xffdf9e, emissiveIntensity: 2 });
  [[-15, -15], [15, -15], [-15, 15], [15, 15]].forEach(([x, z], i) => {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 4.6, 8), poleMat);
    pole.position.set(x, 2.3, z); pole.castShadow = true; scene.add(pole); addCollider(pole, 0.05);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.28, 12, 10), lampMat);
    head.position.set(x, 4.7, z); scene.add(head);
    if (i < 2) {
      const pl = new THREE.PointLight(0xffcc88, 30, 22, 1.8);
      pl.position.set(x, 4.6, z); scene.add(pl);
    }
  });
}
// supply crate (hold F to refill)
const supply = new THREE.Mesh(
  new THREE.BoxGeometry(1.4, 1.0, 1.4),
  new THREE.MeshStandardMaterial({ color: 0x1f6f3a, roughness: 0.5, metalness: 0.3, emissive: 0x0a3d1e, emissiveIntensity: 0.8 })
);
supply.position.set(0, 0.5, -3); supply.castShadow = true;
scene.add(supply); addCollider(supply, 0.05);
const supplyRing = new THREE.Mesh(
  new THREE.RingGeometry(1.6, 2.1, 40),
  new THREE.MeshBasicMaterial({ color: 0x37d67a, transparent: true, opacity: 0.55, side: THREE.DoubleSide })
);
supplyRing.rotation.x = -Math.PI / 2; supplyRing.position.set(0, 0.03, -3);
scene.add(supplyRing);

// distant mountains + clouds for depth
{
  const mMat = new THREE.MeshStandardMaterial({ color: 0x5a6a7a, roughness: 1 });
  for (let i = 0; i < 10; i++) {
    const h = rnd(14, 30);
    const m = new THREE.Mesh(new THREE.ConeGeometry(rnd(14, 24), h, 5), mMat);
    const a = i / 10 * Math.PI * 2;
    m.position.set(Math.cos(a) * rnd(110, 150), h / 2 - 2, Math.sin(a) * rnd(110, 150));
    scene.add(m);
  }
  const cMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.75 });
  for (let i = 0; i < 8; i++) {
    const c = new THREE.Mesh(new THREE.SphereGeometry(rnd(4, 8), 10, 8), cMat);
    c.position.set(rnd(-120, 120), rnd(40, 70), rnd(-120, 120));
    c.scale.y = 0.45; scene.add(c);
  }
}

/* ---------- audio (all procedural) ---------- */
let AC = null, masterGain = null, muted = false;
function audio() {
  if (!AC) {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = AC.createGain(); masterGain.gain.value = 0.8; masterGain.connect(AC.destination);
    startWind();
  }
  if (AC.state === 'suspended') AC.resume();
}
function noiseBuf(dur) {
  const b = AC.createBuffer(1, AC.sampleRate * dur, AC.sampleRate);
  const d = b.getChannelData(0);
  for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  return b;
}
function playShot() {
  if (!AC || muted) return;
  const t = AC.currentTime;
  const n = AC.createBufferSource(); n.buffer = noiseBuf(0.2);
  const f = AC.createBiquadFilter(); f.type = 'lowpass';
  f.frequency.setValueAtTime(3400, t); f.frequency.exponentialRampToValueAtTime(350, t + 0.16);
  const g = AC.createGain(); g.gain.setValueAtTime(0.9, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
  n.connect(f); f.connect(g); g.connect(masterGain); n.start(t); n.stop(t + 0.2);
  const o = AC.createOscillator(); o.type = 'square';
  o.frequency.setValueAtTime(150, t); o.frequency.exponentialRampToValueAtTime(45, t + 0.1);
  const og = AC.createGain(); og.gain.setValueAtTime(0.5, t); og.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
  o.connect(og); og.connect(masterGain); o.start(t); o.stop(t + 0.13);
}
function playClick(freq = 2200, dur = 0.05, gain = 0.3) {
  if (!AC || muted) return;
  const t = AC.currentTime;
  const o = AC.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
