const fx = [];
function spawnBurst(pos, { n = 14, color = 0xffcc66, speed = 5, size = 0.05, life = 0.4, gravity = -9, grow = 0 }) {
  const geo = new THREE.BufferGeometry();
  const p = new Float32Array(n * 3), v = [];
  for (let i = 0; i < n; i++) {
    p[i*3] = pos.x; p[i*3+1] = pos.y; p[i*3+2] = pos.z;
    const th = rnd(0, Math.PI * 2), ph = rnd(-1, 1);
    const sp = rnd(speed * 0.3, speed);
    v.push(new THREE.Vector3(Math.cos(th) * sp, Math.abs(ph) * sp * 0.9 + 1, Math.sin(th) * sp));
  }
  geo.setAttribute('position', new THREE.BufferAttribute(p, 3));
  const mat = new THREE.PointsMaterial({ color, size, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending });
  const pts = new THREE.Points(geo, mat);
  scene.add(pts);
  fx.push({ pts, v, life, age: 0, gravity, grow, mat });
}
function spawnSmoke(pos, n = 6, color = 0x9a938a) {
  const geo = new THREE.BufferGeometry();
  const p = new Float32Array(n * 3), v = [];
  for (let i = 0; i < n; i++) {
    p[i*3] = pos.x + rnd(-0.1, 0.1); p[i*3+1] = pos.y; p[i*3+2] = pos.z + rnd(-0.1, 0.1);
    v.push(new THREE.Vector3(rnd(-0.5, 0.5), rnd(0.6, 1.6), rnd(-0.5, 0.5)));
  }
  geo.setAttribute('position', new THREE.BufferAttribute(p, 3));
  const mat = new THREE.PointsMaterial({ color, size: 0.25, transparent: true, opacity: 0.4, depthWrite: false });
  const pts = new THREE.Points(geo, mat);
  scene.add(pts);
  fx.push({ pts, v, life: 1.0, age: 0, gravity: 1.2, grow: 0.5, mat, smoke: true });
}
function updateFx(dt) {
  for (let i = fx.length - 1; i >= 0; i--) {
    const f = fx[i]; f.age += dt;
    const k = f.age / f.life;
    if (k >= 1) { scene.remove(f.pts); f.pts.geometry.dispose(); f.mat.dispose(); fx.splice(i, 1); continue; }
    const p = f.pts.geometry.attributes.position.array;
    for (let j = 0; j < f.v.length; j++) {
      f.v[j].y += f.gravity * dt;
      p[j*3] += f.v[j].x * dt; p[j*3+1] += f.v[j].y * dt; p[j*3+2] += f.v[j].z * dt;
      if (p[j*3+1] < 0.02 && !f.smoke) { p[j*3+1] = 0.02; f.v[j].set(0, 0, 0); }
    }
    f.pts.geometry.attributes.position.needsUpdate = true;
    f.mat.opacity = f.smoke ? 0.4 * (1 - k) : 1 - k;
    if (f.grow) f.mat.size += f.grow * dt;
  }
}
