}
function killEnemy(e, head) {
  e.dead = true; e.deathT = 0;
  player.kills++; player.score += head ? 150 : 100;
  feed(`Hostile down <b>+${head ? 150 : 100}</b>${head ? ' · HEADSHOT' : ''}`);
  playDeath();
  spawnBurst(e.g.position.clone().add(new THREE.Vector3(0, 1.3, 0)), { n: 18, color: 0x881111, speed: 4, size: 0.09, life: 0.6 });
