    if (enemyHitMeshes[i].userData.enemy === e) enemyHitMeshes.splice(i, 1);
}
const pickups = [];
function updateEnemies(dt) {
  // spawn logic
  if (waveState === 'fight' && toSpawn > 0) {
    spawnT -= dt;
    const alive = enemies.filter(e => !e.dead).length;
    if (spawnT <= 0 && alive < Math.min(5 + wave, 11)) {
      spawnEnemy(); toSpawn--; spawnT = Math.max(2.4 - wave * 0.18, 0.7);
    }
  }
  const pp = new THREE.Vector3(player.pos.x, 1.4, player.pos.z);
  for (let i = enemies.length - 1; i >= 0; i--) {
    const e = enemies[i];
    if (e.dead) {
      e.deathT += dt;
      e.g.rotation.x = Math.min(e.deathT * 3, Math.PI / 2);
      e.g.position.y = -Math.min(e.deathT * 0.4, 0.35);
      e.bg.material.opacity = e.fg.material.opacity = Math.max(1 - e.deathT / 2, 0);
      e.bg.material.transparent = e.fg.material.transparent = true;
      if (e.deathT > 2.2) { scene.remove(e.g); enemies.splice(i, 1); }
      continue;
    }
    const toP = new THREE.Vector3().subVectors(player.pos, e.g.position); toP.y = 0;
    const dist = toP.length(); toP.normalize();
    e.g.lookAt(player.pos.x, 0, player.pos.z);
    // walk anim
    e.walkP += dt * (2 + e.speed * 1.6);
    const sw = Math.sin(e.walkP) * 0.55;
    e.parts.legL.rotation.x = sw; e.parts.legR.rotation.x = -sw;
    e.parts.armL.rotation.x = -sw * 0.7; e.parts.armR.rotation.x = -0.9; // aim rifle
    // hit flash
    if (e.flash > 0) {
      e.flash -= dt;
      e.parts.torso.material.emissive = e.parts.torso.material.emissive || new THREE.Color();
    }
    e.fg.scale.x = 0.9 * Math.max(e.hp / e.maxHp, 0);
    e.fg.position.x = -0.45 * (1 - Math.max(e.hp / e.maxHp, 0));
    if (player.dead) continue;
    if (dist > 11) {
      e.g.position.addScaledVector(toP, e.speed * dt);
    } else {
      // strafe orbit
      e.strafeT -= dt;
      if (e.strafeT <= 0) { e.strafeDir *= -1; e.strafeT = rnd(1.5, 3.5); }
      const side = new THREE.Vector3(-toP.z, 0, toP.x).multiplyScalar(e.strafeDir * 1.8 * dt);
      e.g.position.add(side);
      if (dist < 6) e.g.position.addScaledVector(toP, -1.5 * dt);
    }
    e.g.position.x = THREE.MathUtils.clamp(e.g.position.x, -ARENA, ARENA);
    e.g.position.z = THREE.MathUtils.clamp(e.g.position.z, -ARENA, ARENA);
