#crosshair{position:absolute;left:50%;top:50%;width:0;height:0}
#crosshair .c{position:absolute;background:rgba(255,255,255,.9);box-shadow:0 0 3px #000}
#crosshair .t{left:-1px;top:calc(-6px - var(--sp,4px));width:2px;height:6px}
#crosshair .b{left:-1px;top:var(--sp,4px);width:2px;height:6px}
#crosshair .l{top:-1px;left:calc(-6px - var(--sp,4px));height:2px;width:6px}
#crosshair .r{top:-1px;left:var(--sp,4px);height:2px;width:6px}
#crosshair .dot{position:absolute;left:-1px;top:-1px;width:2px;height:2px;background:#fff;border-radius:50%}
#hitmarker{position:absolute;left:50%;top:50%;opacity:0;transition:opacity .15s}
#hitmarker span{position:absolute;width:10px;height:2px;background:#fff;box-shadow:0 0 4px #000}
#hitmarker span:nth-child(1){transform:translate(-14px,-11px) rotate(45deg)}
#hitmarker span:nth-child(2){transform:translate(4px,-11px) rotate(-45deg)}
#hitmarker span:nth-child(3){transform:translate(-14px,9px) rotate(-45deg)}
#hitmarker span:nth-child(4){transform:translate(4px,9px) rotate(45deg)}
#hitmarker.show{opacity:1}
#hitmarker.kill span{background:#ff3b3b}
#damage-vignette{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse at center,transparent 45%,rgba(200,0,0,.65) 100%)}
#heal-vignette{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse at center,transparent 55%,rgba(40,200,120,.4) 100%)}
#topbar{position:absolute;top:14px;left:50%;transform:translateX(-50%);display:flex;gap:10px}
.tb-box{background:rgba(8,12,18,.62);border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:6px 18px;text-align:center;backdrop-filter:blur(4px);min-width:110px}
.tb-label{font-size:10px;letter-spacing:2px;color:#9fb2c8}
.tb-val{font-size:22px;font-weight:700}
#killfeed{position:absolute;top:14px;right:164px;display:flex;flex-direction:column;gap:4px;align-items:flex-end;font-size:12px}
.kf{background:rgba(8,12,18,.6);border:1px solid rgba(255,255,255,.12);padding:3px 10px;border-radius:6px}
.kf b{color:#ffd27a}
#hitdir{position:absolute;left:50%;top:50%}
.hd{position:absolute;left:-30px;top:-90px;width:60px;height:40px;background:linear-gradient(to top,rgba(255,40,40,.8),transparent);clip-path:polygon(50% 0,100% 100%,0 100%);opacity:.9}
#bottom-left{position:absolute;left:22px;bottom:22px}
#health-wrap{position:relative;width:280px;height:26px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.2);border-radius:6px;overflow:hidden}
#health-bar{height:100%;width:100%;background:linear-gradient(90deg,#37d67a,#9df0b6);transition:width .2s}
#health-num{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px;text-shadow:0 1px 2px #000}
#armor-wrap{position:relative;width:280px;height:14px;margin-top:6px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.2);border-radius:6px;overflow:hidden}
#armor-bar{height:100%;width:0%;background:linear-gradient(90deg,#3aa0ff,#a8d4ff);transition:width .2s}
#armor-wrap span{position:absolute;inset:0;font-size:9px;letter-spacing:2px;display:flex;align-items:center;justify-content:center;color:#cfe6ff}
#bottom-right{position:absolute;right:22px;bottom:22px;text-align:right}
#ammo{font-size:40px;font-weight:800;text-shadow:0 2px 6px #000}
#ammo-div{color:#8a94a3;font-size:28px;margin:0 6px}
#ammo-reserve{color:#9fb2c8;font-size:26px}
#ammo.low #ammo-mag{color:#ff5b5b;animation:blink 0.6s infinite}
@keyframes blink{50%{opacity:.4}}
#weapon-name{font-size:12px;letter-spacing:1.5px;color:#c8d2de}
#reload-tip{font-size:13px;color:#ffd27a;letter-spacing:2px;margin-top:4px}
#minimap{position:absolute;top:14px;right:14px;border-radius:50%;border:2px solid rgba(255,255,255,.25);background:rgba(5,8,12,.7)}
#wave-banner{position:absolute;top:34%;width:100%;text-align:center;font-size:52px;font-weight:900;letter-spacing:8px;color:#fff;text-shadow:0 0 24px rgba(255,180,80,.8),0 2px 4px #000}
#interact-tip{position:absolute;left:50%;bottom:30%;transform:translateX(-50%);background:rgba(0,0,0,.65);padding:8px 18px;border-radius:8px;border:1px solid #ffd27a;font-size:14px}
/* overlays */
.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 30%,rgba(30,45,70,.88),rgba(4,6,10,.94));z-index:10;backdrop-filter:blur(3px)}
.menu-card{text-align:center;max-width:620px;padding:34px 44px;background:rgba(10,14,20,.75);border:1px solid rgba(255,255,255,.12);border-radius:16px;box-shadow:0 20px 80px rgba(0,0,0,.6)}
.kicker{font-size:12px;letter-spacing:4px;color:#ffd27a;margin-bottom:6px}
.kicker.red{color:#ff5b5b}
h1{font-size:64px;letter-spacing:6px;font-weight:900;background:linear-gradient(180deg,#fff,#9fb2c8);-webkit-background-clip:text;background-clip:text;color:transparent}
h2{font-size:40px;letter-spacing:4px}
.sub{color:#9fb2c8;margin:10px 0 18px;font-size:14px}
.controls-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}
.controls-grid div{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:8px}
.controls-grid b{display:block;font-size:13px;color:#ffd27a}
.controls-grid span{font-size:11px;color:#9fb2c8}
.menu-row{display:flex;gap:18px;justify-content:center;align-items:center;margin-bottom:18px;font-size:13px;flex-wrap:wrap}
.menu-row input[type=range]{vertical-align:middle}
.big-btn{pointer-events:auto;cursor:pointer;font-size:20px;font-weight:800;letter-spacing:3px;padding:14px 54px;border:none;border-radius:10px;background:linear-gradient(180deg,#ffcf6e,#e8930c);color:#1a1206;box-shadow:0 6px 30px rgba(232,147,12,.45)}
.big-btn:hover{filter:brightness(1.08)}
.ghost-btn{pointer-events:auto;cursor:pointer;display:block;margin:12px auto 0;background:transparent;border:1px solid rgba(255,255,255,.3);color:#fff;padding:8px 26px;border-radius:8px}
.foot{margin-top:12px;font-size:11px;color:#66788e}
#final-stats{margin:14px 0;font-size:16px;line-height:1.8}
#toast{position:absolute;bottom:120px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.7);border:1px solid rgba(255,255,255,.2);padding:8px 20px;border-radius:8px;z-index:9;font-size:14px}
#fps-counter{position:absolute;left:10px;top:8px;font-size:11px;color:#5f7288;z-index:6}
button,label,input,select{pointer-events:auto}

