(async () => {
  const exe = '/Users/runner/Library/Caches/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-mac-arm64/chrome-headless-shell';
  const browser = await chromium.launch({ executablePath: exe, args: ['--enable-unsafe-swiftshader', '--use-angle=swiftshader', '--no-sandbox'] });
  const errors = [];
  // 1) menu
  const p1 = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  p1.on('pageerror', e => errors.push('MENU PAGEERROR: ' + e.message));
  p1.on('console', m => { if (m.type() === 'error') errors.push('MENU CONSOLE: ' + m.text()); });
  await p1.goto('http://127.0.0.1:8765/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await p1.waitForFunction('window.__ready === true', null, { timeout: 30000 });
  await p1.waitForTimeout(2500);
  await p1.screenshot({ path: '/tmp/shot/menu.png' });
  const webgl = await p1.evaluate(() => { const c = document.createElement('canvas'); return !!(c.getContext('webgl2') || c.getContext('webgl')); });
  console.log('WEBGL_OK=' + webgl);
  await p1.close();
  // 2) gameplay autostart
  const p2 = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  p2.on('pageerror', e => errors.push('GAME PAGEERROR: ' + e.message));
  p2.on('console', m => { if (m.type() === 'error') errors.push('GAME CONSOLE: ' + m.text().slice(0, 300)); });
  await p2.goto('http://127.0.0.1:8765/index.html?autostart=1', { waitUntil: 'networkidle', timeout: 45000 });
  await p2.waitForFunction('window.__ready === true', null, { timeout: 30000 });
  await p2.waitForTimeout(9000);
  const st = await p2.evaluate(() => { const g = window.__game || {}; return JSON.stringify({ state: g.state, bots: (g.bots || []).length, hp: g.player && Math.round(g.player.hp), wave: g.wave, kills: g.kills }); });
  console.log('STATE=' + st);
  await p2.screenshot({ path: '/tmp/shot/game.png' });
  // 3) look toward action: rotate camera via exposed game (yaw spin already in demo?) just capture second angle
  await p2.waitForTimeout(4000);
  await p2.screenshot({ path: '/tmp/shot/game2.png' });
  await browser.close();
  console.log('ERRORS=' + errors.length);
  errors.slice(0, 10).forEach(e => console.log(e));
})().catch(e => { console.error('FATAL', e); process.exit(1); });

