import { chromium } from 'playwright-core';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = '/Users/runner/work/PlayGround/PlayGround/project';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.glb': 'model/gltf-binary', '.json': 'application/json' };

async function serveFromDisk(route) {
  const u = new URL(route.request().url());
  let p = path.join(ROOT, decodeURIComponent(u.pathname));
  if (u.pathname === '/' || u.pathname === '') p = path.join(ROOT, 'index.html');
  try {
    const body = fs.readFileSync(p);
    await route.fulfill({ status: 200, contentType: MIME[path.extname(p)] || 'application/octet-stream', body });
  } catch { await route.fulfill({ status: 404, body: 'nf' }); }
}

const exe = '/Users/runner/Library/Caches/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-mac-arm64/chrome-headless-shell';
const browser = await chromium.launch({ executablePath: exe, args: ['--enable-unsafe-swiftshader', '--use-angle=swiftshader', '--no-sandbox'] });
const errors = [];
try {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  await ctx.route('http://127.0.0.1:8765/**', serveFromDisk);
  const p1 = await ctx.newPage();
  p1.on('pageerror', e => errors.push('MENU PAGEERROR: ' + e.message));
  p1.on('console', m => { if (m.type() === 'error') errors.push('MENU CONSOLE: ' + m.text().slice(0, 250)); });
  await p1.goto('http://127.0.0.1:8765/index.html', { waitUntil: 'load', timeout: 30000 });
  await p1.waitForFunction('window.__ready === true', null, { timeout: 30000 });
  await p1.waitForTimeout(2500);
  await p1.screenshot({ path: '/tmp/shot/menu.png' });
  console.log('MENU_SHOT_OK');
  await p1.close();
  const p2 = await ctx.newPage();
  p2.on('pageerror', e => errors.push('GAME PAGEERROR: ' + e.message));
  p2.on('console', m => { if (m.type() === 'error') errors.push('GAME CONSOLE: ' + m.text().slice(0, 250)); });
  await p2.goto('http://127.0.0.1:8765/index.html?autostart=1', { waitUntil: 'load', timeout: 30000 });
  await p2.waitForFunction('window.__ready === true', null, { timeout: 30000 });
  await p2.waitForTimeout(9000);
  const st = await p2.evaluate(() => { const g = window.__game || {}; return JSON.stringify({ state: g.state, bots: (g.bots || []).length, hp: g.player && Math.round(g.player.hp), wave: g.wave, kills: g.kills, glb: !!g.soldierReady }); });
  console.log('STATE=' + st);
  await p2.screenshot({ path: '/tmp/shot/game.png' });
  await p2.waitForTimeout(5000);
  await p2.screenshot({ path: '/tmp/shot/game2.png' });
  console.log('GAME_SHOT_OK');
  await ctx.close();
} catch (e) { console.error('FATAL', e.message); }
await browser.close();
console.log('ERRORS=' + errors.length);
[...new Set(errors)].slice(0, 12).forEach(e => console.log(e));

