await pg.waitForTimeout(6000);
const info = await pg.evaluate(() => {
  const g = window.__game;
  return (g.bots || []).filter(b => b.alive).map(b => ({
    scale: +b.grp.scale.x.toFixed(6),
    pos: b.grp.position.toArray().map(v => +v.toFixed(2)),
    dist: +b.grp.position.distanceTo(g.player.pos).toFixed(2),
    mats: (() => { const s = new Set(); b.grp.traverse(o => { if (o.isMesh) s.add(o.material.uuid); }); return s.size; })(),
  }));
});
console.log(JSON.stringify(info, null, 1));
console.log('ERRS=' + JSON.stringify(errs.slice(0, 5)));
await browser.close();

